#!/usr/bin/env python3
import base64,zlib,json,hashlib,os,subprocess,sys,re,shutil
from pathlib import Path
ROOT=Path('/root/claude-rel')
PRE=ROOT/'pre298-live'
FLAG='MONTAGE_NOTIFICATIONS_ENABLED'
def run(args,**kw):
 return subprocess.run(args,capture_output=True,check=True,timeout=45,**kw).stdout
def sha(b):return hashlib.sha256(b).hexdigest()
def save(p,b):
 p.parent.mkdir(mode=0o700,parents=True,exist_ok=True)
 with os.fdopen(os.open(p,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600),'wb') as f:f.write(b)
def live(row):
 p=row['path']
 if p.startswith('sites/'):
  f=Path('/opt/synapse')/p;return f.read_bytes() if f.exists() else None
 service=p.split('/')[1];name=p.split('/')[-1];c='synapse-'+service+'-1'
 r=subprocess.run(['docker','exec',c,'test','-f','/app/'+name],capture_output=True,timeout=15)
 if r.returncode==1:return None
 r.check_returncode();return run(['docker','exec',c,'cat','/app/'+name])
def state(s):
 d=json.loads(run(['docker','inspect','synapse-'+s+'-1']))[0]
 flags=[x.partition('=')[2] for x in d['Config']['Env'] if x.startswith(FLAG+'=')]
 return {'image':d['Image'],'status':d['State']['Status'],'restarts':d['RestartCount'],'flag':flags[0] if flags else None}
def inspect():
 PRE.mkdir(mode=0o700)
 for s in ['crm','content']:
  d=state(s);save(PRE/(s+'.json'),json.dumps(d).encode());print('LIVE',s,json.dumps(d))
 for name in ['prpatch.sh','prgo.sh','rel.sh']:
  b=(ROOT/name).read_bytes();save(PRE/name,b);print('SCRIPT',name,sha(b))
 # The existing script has no credentials. Print only the generic overlay recipe.
 lines=(ROOT/'prpatch.sh').read_text().splitlines()
 print('OVERLAY_RECIPE\n'+'\n'.join(lines[18:]))
 for row in DATA['files']:
  b=live(row);name=row['path'].replace('/','__')
  if b is not None:save(PRE/'before'/name,b)
  print('FILE',row['path'],sha(b) if b is not None else 'ABSENT')
 print('DISK',run(['df','-h','/']).decode().splitlines()[-1])
 # No user content, credentials or event text is returned.
 program=r'''
const {DatabaseSync}=require('node:sqlite');const db=new DatabaseSync('/data/crm.sqlite',{readOnly:true});
for(const n of ['reel_notification_settings','reel_notification_events','reel_notification_reads']){
 const exists=!!db.prepare("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?").get(n);
 console.log(JSON.stringify({table:n,exists,...(exists?{count:db.prepare('SELECT count(*) AS n FROM '+n).get().n}:{})}));
}db.close();
'''
 r=subprocess.run(['docker','exec','-i','synapse-crm-1','node'],input=program.encode(),capture_output=True,timeout=15)
 print('NOTIFICATION_TABLES',r.stdout.decode().strip() if r.returncode==0 else 'READ_UNAVAILABLE')
 return 0
def preflight():
 receipt={'files':[],'ok':False}
 for s in ['crm','content']:
  if state(s)!=json.loads((PRE/(s+'.json')).read_text()):raise RuntimeError('live service changed '+s)
 for row in DATA['files']:
  path=row['path'];name=path.replace('/','__');original=live(row)
  before=PRE/'before'/name
  if original!=(before.read_bytes() if before.exists() else None):raise RuntimeError('live changed '+path)
  if original is not None and sha(original)==row['targetSha256']:
   print('SKIP_ALREADY',path);receipt['files'].append({'path':path,'skip':True,'sha':sha(original)});continue
  target=PRE/'candidates'/name
  patch=base64.b64decode(row['patchData'])
  if sha(patch)!=row['patchSha256']:raise RuntimeError('package patch changed')
  if row['new']:
   if original is not None:raise RuntimeError('unknown existing new file '+path)
   result=base64.b64decode(row['newData'])
   if sha(result)!=row['targetSha256']:raise RuntimeError('new target changed')
   save(target,result)
  else:
   if original is None:raise RuntimeError('existing file absent '+path)
   # Full contexts must each occur exactly once; GNU patch uses zero fuzz.
   chunks=re.split(rb'(?m)^@@[^\n]*\n',patch)[1:]
   for chunk in chunks:
    old=b''.join(l[1:] for l in chunk.splitlines(keepends=True) if l.startswith((b' ',b'-')))
    if not old or original.count(old)!=1:raise RuntimeError('nonunique or missing hunk '+path)
   save(target,original);pp=PRE/'patches'/name;save(pp,patch)
   run(['patch','--dry-run','--batch','--forward','--fuzz=0',str(target),str(pp)])
   run(['patch','--batch','--forward','--fuzz=0',str(target),str(pp)])
   result=target.read_bytes();undo=PRE/'undo'/name;save(undo,result)
   run(['patch','--batch','--reverse','--fuzz=0',str(undo),str(pp)])
   if undo.read_bytes()!=original:raise RuntimeError('undo mismatch '+path)
  if path.endswith('.js'):
   service=row['kind'] if row['kind'] in ['crm','content'] else 'content'
   run(['docker','exec','-i','synapse-'+service+'-1','node','--check'],input=result)
  entry={'path':path,'skip':False,'before':sha(original) if original is not None else None,'sha':sha(result),'bytes':len(result),'undo':True}
  receipt['files'].append(entry);print('CANDIDATE',json.dumps(entry))
 receipt['ok']=True;save(PRE/'receipt.json',json.dumps(receipt,indent=2).encode());print('PREFLIGHT298_OK',len(receipt['files']))
 return 0
def main():
 if sys.argv[1:]==['inspect']:return inspect()
 if sys.argv[1:]==['preflight']:return preflight()
 raise RuntimeError('unknown mode')
DATA=json.loads(zlib.decompress(base64.b64decode('')))

if __name__=="__main__":
 try:sys.exit(main())
 except Exception as e:
  print("STOP298",type(e).__name__,str(e) if isinstance(e,RuntimeError) else "command failed; private output withheld");sys.exit(1)
